use vstd::prelude::*;

verus! {

spec fn slice_view_i32(a: &[i32]) -> Seq<i32> {
    Seq::<i32>::new(a.len() as nat, |i: nat| a[i as int])
}

fn array_to_seq(a: &[i32]) -> (s: Vec<i32>)
    ensures
        s@ == slice_view_i32(a),
        s@.len() == a.len() as nat,
{
    // Allocate a new vector and copy elements in order.
    let mut s = Vec::with_capacity(a.len());

    for &x in a
        invariant
            s@.len() <= a.len() as nat,
            s@ == slice_view_i32(a).subrange(0, s@.len() as int),
    {
        s.push(x);

        // After pushing, the prefix relation extends by one element.
        assert(s@ == slice_view_i32(a).subrange(0, s@.len() as int));
    }

    s
}

}

